const items = $input.all();

function getPreviousWorkingDay() {
  const date = new Date();
    date.setDate(date.getDate() -1);

    while (date.getDay() === 0 || date.getDay() === 6) {
      date.setDate(date.getDate() -1);
    }

    return date.toISOString().split('T') [0];
  }

  const dataKursu = getPreviousWorkingDay();

  return [{
    json: {
      dataKursu: dataKursu,
      nbpUrl: `https://api.nbp.pl/api/exchangerates/tables/A/${dataKursu}/?format=json`,
    orginalData: items.map(item => item.json)
    }
  }];

const items = $input.all();

function getPreviousWorkingDay() {
  const date = new Date();
    date.setDate(date.getDate() -1);

    while (date.getDay() === 0 || date.getDay() === 6) {
      date.setDate(date.getDate() -1);
    }

    return date.toISOString().split('T') [0];
  }

  const dataKursu = getPreviousWorkingDay();

  return [{
    json: {
      dataKursu: dataKursu,
      nbpUrl: `https://api.nbp.pl/api/exchangerates/tables/A/${dataKursu}/?format=json`,
    orginalData: items.map(item => item.json)
    }
  }];

// Flatten Empik orders
const flattenedOrders = [];

for (const item of $input.all()) {
  if (item.json.orders && Array.isArray(item.json.orders)) {
    for (const order of item.json.orders) {
      flattenedOrders.push({
        json: {
          ...order,
          platform: 'Empik'  // dodaj platform identifier
        }
      });
    }
  }
}

return flattenedOrders;

// Parse JSON string z data field
const rawData = JSON.parse($json.data);

// chceckoutForms array
const checkoutForms = rawData.checkoutForms;

// For Sheets
const processedOrders = checkoutForms.map(order => {
  // Basic info
  const orderInfo = {
    // ID
    orderID: order.id,
    status: order.status,
    fulfillmentStatus: order.fulfillment?.status || null,
    updatedAt: order.updatedAt,

    // Buyer info
    buyerID: order.buyer?.id || null,
    buyerEmail: order.buyer?.email || null,
    buyerLogin: order.buyer?.login || null,
    buyerFirstName: order.buyer?.firstName || null,
    buyerLastName: order.buyer?.lastName || null,
buyerPhone: order.buyer.phoneNumber?.replace(/\s/g, '') || null,    
                                             // Buyer address
    buyerStreet: order.buyer?.address?.street || null,
    buyerCity: order.buyer?.address?.city || null,
    buyerPostCode: order.buyer?.address?.postCode || null,
    buyerCountry: order.buyer?.address?.countryCode || null,

    // Payment info
        paymentID: order.payment?.id || null,
    paymentType: order.payment?.type || null,
    paymentProvider: order.payment?.provider || null,
    paymentFinished: order.payment?.finishedAt || null,
    paidAmount: order.payment?.paidAmount?.amount || 0,
    currency: order.payment?.paidAmount?.currency || null,

    // Delivery info
    deliveryFirstName: order.delivery?.address?.firstName || null,
    deliveryLastName: order.delivery?.address?.lastName || null,
    deliveryStreet: order.delivery?.address?.street || null,
    deliveryCity: order.delivery?.address?.city || null,
    deliveryZipCode: order.delivery?.address?.zipCode || null,
    deliveryPhone: order.delivery?.address?.phoneNumber || null,
    deliveryMethod: order.delivery?.method?.name || null,
    deliveryCost: order.delivery?.cost?.amount || 0,

    // Pickup Point (jeśli istnieje)
    pickupPointID: order.delivery?.pickupPoint?.id || null,
    pickupPointName: order.delivery?.pickupPoint?.name || null,
    pickupPointAddress: order.delivery?.pickupPoint?.address?.street || null,

    // Totals
    totalToPay: order.summary?.totalToPay?.amount || 0,
    totalCurrency: order.summary?.totalToPay?.currency || null,

    // Message to seller
    messageToSeller: order.messageToSeller || null,

    // Line items (produkty) - jako string dla prostoty
    products: (order.lineItems ||  []).map(item => 
      `${item.offer?.name || 'Unknown'} (qty: ${item.quantity || 0}, price: ${item.price?.amount || 0})`
    ).join(' | '),

    // Liczba produktów
    itemsCount: order.lineItems?.length || 0,

    // Platform
    platform: 'Allegro'
  };

  return orderInfo;
});

// Zwróć każde zamówienie jako osobny item
return processedOrders.map(order => ({ json: order }));

